Value.Calculation:
Let ( [
	~p = Trim ( Get ( ScriptParameter ) ) ;
	~y = If ( IsEmpty ( ~p ) ; 0 ; GetAsNumber ( ~p ) )
] ;
If ( ~y < 2000 or ~y > 2100 ; 0 ; ~y )
)

Let ( [
	~today = Get ( CurrentDate ) ;
	~py = Year ( ~today ) - 1 ;
	~m = Month ( ~today ) ;
	~d = Day ( ~today ) ;
	~last = Day ( Date ( ~m + 1 ; 1 ; ~py ) - 1 )
] ;
Date ( ~m ; Min ( ~d ; ~last ) ; ~py )
)

JSONSetElement (
	"{}" ;
	[ "ok" ; 1 ; JSONNumber ] ;
	[ "message" ; "No flights found" ; JSONString ] ;
	[ "period.start" ; GetAsText ( $startDate ) ; JSONString ] ;
	[ "period.end" ; GetAsText ( $endDate ) ; JSONString ] ;
	[ "period.label" ; $periodLabel ; JSONString ] ;
	[ "period.key" ; $period ; JSONString ] ;
	[ "kpi.missions" ; 0 ; JSONNumber ] ;
	[ "kpi.flightHours" ; 0 ; JSONNumber ] ;
	[ "kpi.ifrHours" ; 0 ; JSONNumber ] ;
	[ "kpi.nvgHours" ; 0 ; JSONNumber ] ;
	[ "kpi.nightHours" ; 0 ; JSONNumber ] ;
	[ "types" ; "[]" ; JSONArray ] ;
	[ "typeBaseFlights" ; "[]" ; JSONArray ] ;
	[ "typePilotFlights" ; "[]" ; JSONArray ]
)

Let ( [
	~stored = GetAsNumber ( AM_Imported_Flights::MissionCount ) ;
	~isSto = Left ( $base ; 4 ) = "STO "
		or $base = "Stockholm"
		or PatternCount ( $base ; "Stockholm" ) > 0 ;
	~legs = If (
		~isSto
		and not IsEmpty ( AM_Imported_Flights::JsonFlightRaw )
		and JSONGetElementType ( AM_Imported_Flights::JsonFlightRaw ; "Legs" ) = JSONArray ;
		ValueCount ( JSONListKeys ( AM_Imported_Flights::JsonFlightRaw ; "Legs" ) ) ;
		""
	) ;
	~legsN = GetAsNumber ( ~legs )
] ;
Case (
	~isSto and ~legsN > 0 ; ~legsN ;
	~stored > 0 ; ~stored ;
	1
)
)

Let ( [
	~fIfr = GetAsNumber ( AM_Imported_Flights::IFRTimeDecimal ) ;
	~fNvg = GetAsNumber ( AM_Imported_Flights::NVGTimeDecimal ) ;
	~fNight = GetAsNumber ( AM_Imported_Flights::NightTimeDecimal ) ;
	~need = ( IsEmpty ( ~fIfr ) or ~fIfr ≤ 0 )
		or ( IsEmpty ( ~fNvg ) or ~fNvg ≤ 0 )
		or ( IsEmpty ( ~fNight ) or ~fNight ≤ 0 ) ;
	~sql = If ( ~need ;
		ExecuteSQL ( "SELECT
 SUM ( IFRHours ),
 SUM ( CommandNight ),
 SUM ( NVGHours )
FROM AM_FlightPersonnel
WHERE Deleted = 0
 AND FlightId = ?
 AND ( CommandDay > 0 OR CommandNight > 0 )" ; "|" ; "" ; AM_Imported_Flights::FlightId ) ;
		""
	) ;
	~parts = If ( IsEmpty ( ~sql ) or ~sql = "?" ; "" ; Substitute ( ~sql ; "|" ; "¶" ) ) ;
	~pIfr = GetAsNumber ( Substitute ( GetValue ( ~parts ; 1 ) ; "." ; "," ) ) ;
	~pNight = GetAsNumber ( Substitute ( GetValue ( ~parts ; 2 ) ; "." ; "," ) ) ;
	~pNvg = GetAsNumber ( Substitute ( GetValue ( ~parts ; 3 ) ; "." ; "," ) )
] ;
JSONSetElement ( "{}" ;
	[ "ifr" ; If ( ~fIfr > 0 and ~fIfr ≤ 24 ; ~fIfr ; If ( ~pIfr > 0 and ~pIfr ≤ 24 ; Round ( ~pIfr ; 2 ) ; 0 ) ) ; JSONNumber ] ;
	[ "nvg" ; If ( ~fNvg > 0 and ~fNvg ≤ 24 ; ~fNvg ; If ( ~pNvg > 0 and ~pNvg ≤ 24 ; Round ( ~pNvg ; 2 ) ; 0 ) ) ; JSONNumber ] ;
	[ "night" ; If ( ~fNight > 0 and ~fNight ≤ 24 ; ~fNight ; If ( ~pNight > 0 and ~pNight ≤ 24 ; Round ( ~pNight ; 2 ) ; 0 ) ) ; JSONNumber ]
)
)

JSONSetElement (
	$types ;
	[ $type & ".type" ; $type ; JSONString ] ;
	[ $type & ".missions" ; $oldMissions + $missions ; JSONNumber ] ;
	[ $type & ".hours" ; Round ( $oldHours + $hours ; 1 ) ; JSONNumber ] ;
	[ $type & ".ifr" ; Round ( $oldIFR + $ifr ; 1 ) ; JSONNumber ] ;
	[ $type & ".nvg" ; Round ( $oldNVG + $nvg ; 1 ) ; JSONNumber ] ;
	[ $type & ".night" ; Round ( $oldNight + $night ; 1 ) ; JSONNumber ] ;
	[ $type & ".day" ; Round ( ( $oldHours + $hours ) - ( $oldNight + $night ) ; 1 ) ; JSONNumber ]
)

JSONSetElement (
	$typeBases ;
	[ $tbfKey & ".type" ; $type ; JSONString ] ;
	[ $tbfKey & ".base" ; $base ; JSONString ] ;
	[ $tbfKey & ".missions" ; $tbfOldMissions + $missions ; JSONNumber ] ;
	[ $tbfKey & ".hours" ; Round ( $tbfOldHours + $hours ; 1 ) ; JSONNumber ]
)

JSONSetElement (
			$typePilotMap ;
			[ $tpfKey & ".type" ; $tpfType ; JSONString ] ;
			[ $tpfKey & ".pilot" ; $tpfPilot ; JSONString ] ;
			[ $tpfKey & ".missions" ; $tpfOldMissions + $tpfMissions ; JSONNumber ] ;
			[ $tpfKey & ".hours" ; Round ( $tpfOldHours + $tpfHours ; 1 ) ; JSONNumber ]
		)

JSONSetElement (
		"{}" ;
		[ "ok" ; 1 ; JSONNumber ] ;
		[ "period.start" ; GetAsText ( $startDate ) ; JSONString ] ;
		[ "period.end" ; GetAsText ( $endDate ) ; JSONString ] ;
		[ "period.label" ; $periodLabel ; JSONString ] ;
		[ "period.key" ; $period ; JSONString ] ;
		[ "kpi.missions" ; $totalMissions ; JSONNumber ] ;
		[ "kpi.flightHours" ; Round ( $totalHours ; 1 ) ; JSONNumber ] ;
		[ "kpi.ifrHours" ; Round ( $totalIFR ; 1 ) ; JSONNumber ] ;
		[ "kpi.nvgHours" ; Round ( $totalNVG ; 1 ) ; JSONNumber ] ;
		[ "kpi.nightHours" ; Round ( $totalNight ; 1 ) ; JSONNumber ] ;
		[ "types" ; $typeArray ; JSONArray ] ;
		[ "typeBaseFlights" ; $typeBaseFlights ; JSONArray ] ;
		[ "typePilotFlights" ; $typePilotFlights ; JSONArray ]
	)

JSONSetElement ( "{}" ;
	[ "ok" ; 1 ; JSONNumber ] ;
	[ "mode" ; "yoy" ; JSONString ] ;
	[ "period.key" ; "yoy" ; JSONString ] ;
	[ "period.label" ; "YTD " & ( Year ( Get ( CurrentDate ) ) - 1 ) & " vs " & Year ( Get ( CurrentDate ) ) ; JSONString ] ;
	[ "period.through" ; GetAsText ( Get ( CurrentDate ) ) ; JSONString ] ;
	[ "period.priorYear" ; Year ( Get ( CurrentDate ) ) - 1 ; JSONNumber ] ;
	[ "period.currYear" ; Year ( Get ( CurrentDate ) ) ; JSONNumber ] ;
	[ "period.priorStart" ; JSONGetElement ( $yoyPriorJson ; "period.start" ) ; JSONString ] ;
	[ "period.priorEnd" ; JSONGetElement ( $yoyPriorJson ; "period.end" ) ; JSONString ] ;
	[ "period.currStart" ; JSONGetElement ( $result ; "period.start" ) ; JSONString ] ;
	[ "period.currEnd" ; JSONGetElement ( $result ; "period.end" ) ; JSONString ] ;
	[ "kpi.prior" ; JSONGetElement ( $yoyPriorJson ; "kpi" ) ; JSONObject ] ;
	[ "kpi.curr" ; JSONGetElement ( $result ; "kpi" ) ; JSONObject ] ;
	[ "typesPrior" ; If ( JSONGetElement ( $yoyPriorJson ; "types" ) = "?" ; "[]" ; JSONGetElement ( $yoyPriorJson ; "types" ) ) ; JSONArray ] ;
	[ "typesCurr" ; If ( JSONGetElement ( $result ; "types" ) = "?" ; "[]" ; JSONGetElement ( $result ; "types" ) ) ; JSONArray ] ;
	[ "types" ; If ( JSONGetElement ( $result ; "types" ) = "?" ; "[]" ; JSONGetElement ( $result ; "types" ) ) ; JSONArray ] ;
	[ "typeBaseFlights" ; If ( JSONGetElement ( $result ; "typeBaseFlights" ) = "?" ; "[]" ; JSONGetElement ( $result ; "typeBaseFlights" ) ) ; JSONArray ] ;
	[ "typePilotFlights" ; If ( JSONGetElement ( $result ; "typePilotFlights" ) = "?" ; "[]" ; JSONGetElement ( $result ; "typePilotFlights" ) ) ; JSONArray ]
)
